/// <summary>Fetches <c>/journals</c> and maps it to <see cref="Journal"/>.</summary>
internal sealed class JournalSource(Raw.JournalsClient client)
    : IEconomicOpenSource<Journal>
{
    public bool CanCursor => true;

    public bool CanPage => true;

    public async Task<EconomicCursorPage<Journal>> GetCursorPageAsync(
        string? cursor, string? filter, CancellationToken cancellationToken)
    {
        var response = await OpenTransport.SendAsync(
            () => client.GetAllJournalsAsync(cursor: cursor, filter: filter, cancellationToken: cancellationToken),
            "GET /journals").ConfigureAwait(false);

        var items = new List<Journal>(response.Items?.Count ?? 0);
        foreach (var item in response.Items ?? [])
        {
            items.Add(Map(item));
        }

        return new EconomicCursorPage<Journal>(items, response.Cursor);
    }

    public async Task<IReadOnlyList<Journal>> GetPageAsync(
        string? filter, string? sort, int pageSize, int skipPages, CancellationToken cancellationToken)
    {
        var response = await OpenTransport.SendAsync(
            () => client.GetPageOfJournalsAsync(filter: filter, sort: sort, pageSize: pageSize, skipPages: skipPages, cancellationToken: cancellationToken),
            "GET /journals/paged").ConfigureAwait(false);

        var items = new List<Journal>(response?.Count ?? 0);
        foreach (var item in response ?? Array.Empty<Raw.Journal>())
        {
            items.Add(Map(item));
        }

        return items;
    }

    public Task<int> CountAsync(string? filter, CancellationToken cancellationToken) =>
        OpenTransport.SendAsync(
            () => client.GetNumberOfJournalsAsync(filter: filter, cancellationToken: cancellationToken),
            "GET /journals/count");

    internal static Journal Map(Raw.Journal source) => new()
    {
        Number = source.Number,
        BalancingBehavior = source.BalancingBehavior,
        AutoApprove = source.AutoApprove,
        IsStandingJournal = source.IsStandingJournal,
        RequireAdminApproval = source.RequireAdminApproval,
        LockVatCodes = source.LockVatCodes,
        NextVoucherNumber = source.NextVoucherNumber,
        MinimumVoucherNumber = source.MinimumVoucherNumber,
        MaximumVoucherNumber = source.MaximumVoucherNumber,
        CustomerContraAccount = source.CustomerContraAccount,
        SupplierContraAccount = source.SupplierContraAccount,
        CustomerPaymentText = source.CustomerPaymentText,
        SupplierPaymentText = source.SupplierPaymentText,
        Name = source.Name,
        Priority = source.Priority,
        AllowPartialBooking = source.AllowPartialBooking,
        RequireBalancePerVoucherId = source.RequireBalancePerVoucherId,
        RepeatText = source.RepeatText,
        PaymentMessageText = source.PaymentMessageText,
        DefaultDepartment = source.DefaultDepartment,
        AllowedEntryType = source.AllowedEntryType,
        ObjectVersion = source.ObjectVersion,
    };

    internal static Raw.Journal ToGenerated(Journal source) => new()
    {
        Number = source.Number,
        BalancingBehavior = source.BalancingBehavior,
        AutoApprove = source.AutoApprove,
        IsStandingJournal = source.IsStandingJournal,
        RequireAdminApproval = source.RequireAdminApproval,
        LockVatCodes = source.LockVatCodes,
        NextVoucherNumber = source.NextVoucherNumber,
        MinimumVoucherNumber = source.MinimumVoucherNumber,
        MaximumVoucherNumber = source.MaximumVoucherNumber,
        CustomerContraAccount = source.CustomerContraAccount,
        SupplierContraAccount = source.SupplierContraAccount,
        CustomerPaymentText = source.CustomerPaymentText,
        SupplierPaymentText = source.SupplierPaymentText,
        Name = source.Name,
        Priority = source.Priority,
        AllowPartialBooking = source.AllowPartialBooking,
        RequireBalancePerVoucherId = source.RequireBalancePerVoucherId,
        RepeatText = source.RepeatText,
        PaymentMessageText = source.PaymentMessageText,
        DefaultDepartment = source.DefaultDepartment,
        AllowedEntryType = source.AllowedEntryType,
        ObjectVersion = source.ObjectVersion,
    };
}

